import type {Translations} from './study-languages';

// Tuzaklı alıştırmalar (Wohnen 11 A–D). Her soru, öğrencilerin sık yaptığı bir
// hatayı yanlış şık olarak sunar; cevaptan sonra "Tuzak neydi?" açıklaması gelir.
// Cümleler çalışma kitabının konularına göre özgün yazılmıştır.
type Rule='noun'|'adjective'|'possessive'|'haben'|'regular'|'irregular'|'notice'|'polite'|'order'|'reading'|'email';
const r=(tr:string,de:string,en:string,ar:string,uk:string,fr:string):Translations=>[tr,de,en,ar,uk,fr];
const m=(tr:string,en:string,ar:string,uk:string,fr:string):Translations=>[tr,'',en,ar,uk,fr];

export const trapReasons={
 compound:r('Bileşik isimlerde artikeli son kelime belirler: das Schlafzimmer ← das Zimmer, die Haustür ← die Tür, der Kinderwagen ← der Wagen.','Bei zusammengesetzten Nomen bestimmt das letzte Wort den Artikel: das Schlafzimmer ← das Zimmer, die Haustür ← die Tür, der Kinderwagen ← der Wagen.','In compound nouns the last word decides the article: das Schlafzimmer ← das Zimmer, die Haustür ← die Tür, der Kinderwagen ← der Wagen.','في الأسماء المركبة تحدد الكلمة الأخيرة أداة التعريف: das Schlafzimmer ← das Zimmer، die Haustür ← die Tür، der Kinderwagen ← der Wagen.','У складних іменниках артикль визначає останнє слово: das Schlafzimmer ← das Zimmer, die Haustür ← die Tür, der Kinderwagen ← der Wagen.','Dans un nom composé, c’est le dernier mot qui donne l’article : das Schlafzimmer ← das Zimmer, die Haustür ← die Tür, der Kinderwagen ← der Wagen.'),
 pluralOnly:r('Möbel neredeyse her zaman çoğul kullanılır: die Möbel sind … Çoğul isimlerle unsere / eure gelir.','Möbel benutzt man fast immer im Plural: die Möbel sind … Im Plural: unsere / eure.','Möbel is almost always used in the plural: die Möbel sind … Plural nouns take unsere / eure.','كلمة Möbel تُستخدم دائمًا تقريبًا بصيغة الجمع: die Möbel sind … ومع الجمع نستخدم unsere / eure.','Möbel майже завжди вживається в множині: die Möbel sind … З множиною — unsere / eure.','Möbel s’emploie presque toujours au pluriel : die Möbel sind … Au pluriel : unsere / eure.'),
 possGender:r('Kelimeyi sahip seçer (ihr → euer), sonunu ise ismin artikeli belirler: der Balkon → euer, das Bad → euer, die Küche → eure, çoğul → eure.','Der Besitzer bestimmt das Wort (ihr → euer), das Nomen die Endung: der Balkon → euer, das Bad → euer, die Küche → eure, Plural → eure.','The owner picks the word (ihr → euer); the noun picks the ending: der Balkon → euer, das Bad → euer, die Küche → eure, plural → eure.','المالك يحدد الكلمة (ihr → euer)، والاسم يحدد النهاية: der Balkon → euer، das Bad → euer، die Küche → eure، الجمع → eure.','Власник визначає слово (ihr → euer), а іменник — закінчення: der Balkon → euer, das Bad → euer, die Küche → eure, множина → eure.','Le possesseur choisit le mot (ihr → euer), le nom choisit la terminaison : der Balkon → euer, das Bad → euer, die Küche → eure, pluriel → eure.'),
 possOwner:r('sein / ihr sahibine göre seçilir: erkekse sein, kadınsa ihr. Sonu sahip olunan isme göre değişir: ihr Sohn, ihre Tochter, seine Tochter.','Der Besitzer entscheidet: er → sein, sie → ihr. Die Endung kommt vom Nomen: ihr Sohn, ihre Tochter, seine Tochter.','Choose by the owner: a man → sein, a woman → ihr. The ending follows the noun: ihr Sohn, ihre Tochter, seine Tochter.','نختار حسب المالك: للرجل sein وللمرأة ihr. والنهاية حسب الاسم: ihr Sohn، ihre Tochter، seine Tochter.','Обирай за власником: чоловік → sein, жінка → ihr. Закінчення залежить від іменника: ihr Sohn, ihre Tochter, seine Tochter.','On choisit selon le possesseur : un homme → sein, une femme → ihr. La terminaison dépend du nom : ihr Sohn, ihre Tochter, seine Tochter.'),
 theirOne:r('Onlar (sie, çoğul) → ihr. Fiil ist olduğu için Zimmer burada tekil (das): ihr Zimmer. Çoğul olsaydı: ihre Zimmer sind …','sie (Plural) → ihr. Wegen ist ist Zimmer hier Singular: ihr Zimmer. Im Plural: ihre Zimmer sind …','They (sie, plural) → ihr. The verb ist shows that Zimmer is singular (das): ihr Zimmer. In the plural: ihre Zimmer sind …','هم (sie للجمع) → ihr. الفعل ist يدل على أن Zimmer مفرد (das): ihr Zimmer. وفي الجمع: ihre Zimmer sind …','Вони (sie, множина) → ihr. Дієслово ist показує, що Zimmer тут в однині (das): ihr Zimmer. У множині: ihre Zimmer sind …','Ils (sie, pluriel) → ihr. Le verbe ist montre que Zimmer est au singulier (das) : ihr Zimmer. Au pluriel : ihre Zimmer sind …'),
 formal:r('Resmî hitapta Sie / Ihnen / Ihr hep büyük harfle yazılır. Küçük sie “o (kadın)” veya “onlar”, küçük ihr “onun / onların” ya da “siz (hepiniz)” demektir.','Höflich: Sie / Ihnen / Ihr immer groß. Klein bedeuten sie und ihr etwas anderes (sie = eine Frau oder mehrere Personen).','In formal address Sie / Ihnen / Ihr always take a capital letter. Lower-case sie means she or they; lower-case ihr means her, their or you (plural).','في المخاطبة الرسمية تُكتب Sie / Ihnen / Ihr دائمًا بحرف كبير. أما sie بحرف صغير فتعني «هي» أو «هم»، و ihr بحرف صغير تعني «لها / لهم» أو «أنتم».','У ввічливому звертанні Sie / Ihnen / Ihr завжди з великої літери. Мале sie означає «вона» або «вони», мале ihr — «її / їхній» або «ви» (множина).','Au vouvoiement, Sie / Ihnen / Ihr prennent toujours une majuscule. sie en minuscule veut dire « elle » ou « ils / elles » ; ihr en minuscule veut dire « son / leur » ou « vous » (pluriel).'),
 altNeuJung:r('alt kelimesinin iki zıttı var: eşyalar için neu (yeni), insanlar için jung (genç).','alt hat zwei Gegenteile: neu (für Dinge) und jung (für Menschen).','alt has two opposites: neu for things and jung for people.','لكلمة alt ضدّان: neu للأشياء و jung للأشخاص.','alt має два антоніми: neu — для речей, jung — для людей.','alt a deux contraires : neu pour les objets, jung pour les personnes.'),
 adjBase:r('ist / sind’den sonra gelen sıfat ek almaz: Die Küche ist hell. Ek yalnızca isimden önce gelir: die helle Küche.','Nach ist / sind bleibt das Adjektiv ohne Endung: Die Küche ist hell. Endungen nur vor dem Nomen: die helle Küche.','After ist / sind the adjective takes no ending: Die Küche ist hell. Endings appear only before a noun: die helle Küche.','بعد ist / sind لا تأخذ الصفة أي نهاية: Die Küche ist hell. النهايات تأتي فقط قبل الاسم: die helle Küche.','Після ist / sind прикметник без закінчення: Die Küche ist hell. Закінчення — лише перед іменником: die helle Küche.','Après ist / sind, l’adjectif ne prend pas de terminaison : Die Küche ist hell. Les terminaisons viennent seulement devant le nom : die helle Küche.'),
 akkusativ:r('haben, brauchen, suchen, kaufen fiillerinden sonra der → einen olur. das ve die değişmez: ein Sofa, eine Lampe.','Nach haben, brauchen, suchen, kaufen: der → einen (Akkusativ). das und die bleiben: ein Sofa, eine Lampe.','After haben, brauchen, suchen or kaufen, der becomes einen. das and die stay the same: ein Sofa, eine Lampe.','بعد haben و brauchen و suchen و kaufen تتحول der إلى einen. أما das و die فلا تتغيران: ein Sofa، eine Lampe.','Після haben, brauchen, suchen, kaufen: der → einen (знахідний відмінок). das і die не змінюються: ein Sofa, eine Lampe.','Après haben, brauchen, suchen ou kaufen, der devient einen. das et die ne changent pas : ein Sofa, eine Lampe.'),
 pluralZero:r('-er, -el, -en ile biten der / das isimlerinin çoğu çoğulda aynı kalır: das Zimmer → die Zimmer. Yalnızca artikel die olur.','Viele der/das-Nomen auf -er, -el, -en bleiben im Plural gleich: das Zimmer → die Zimmer. Nur der Artikel wird die.','Many der/das nouns ending in -er, -el or -en do not change in the plural: das Zimmer → die Zimmer. Only the article becomes die.','كثير من الأسماء (der/das) المنتهية بـ ‎-er أو ‎-el أو ‎-en لا تتغير في الجمع: das Zimmer → die Zimmer. تتغير الأداة فقط إلى die.','Багато іменників der/das на -er, -el, -en у множині не змінюються: das Zimmer → die Zimmer. Змінюється лише артикль на die.','Beaucoup de noms der/das en -er, -el ou -en ne changent pas au pluriel : das Zimmer → die Zimmer. Seul l’article devient die.'),
 pluralUmlaut:r('Bazı çoğullar ünlü değiştirir: der Stuhl → die Stühle, der Schrank → die Schränke, das Haus → die Häuser. Çoğulu her zaman isimle birlikte öğren.','Manche Plurale haben Umlaut: der Stuhl → die Stühle, der Schrank → die Schränke, das Haus → die Häuser. Lerne den Plural immer mit.','Some plurals change the vowel: der Stuhl → die Stühle, der Schrank → die Schränke, das Haus → die Häuser. Always learn the plural with the noun.','بعض صيغ الجمع يتغير فيها الحرف الصوتي: der Stuhl → die Stühle، der Schrank → die Schränke، das Haus → die Häuser. تعلّم الجمع دائمًا مع الاسم.','Деякі множини змінюють голосний: der Stuhl → die Stühle, der Schrank → die Schränke, das Haus → die Häuser. Завжди вчи множину разом з іменником.','Certains pluriels changent de voyelle : der Stuhl → die Stühle, der Schrank → die Schränke, das Haus → die Häuser. Apprends toujours le pluriel avec le nom.'),
 pluralUng:r('-ung ile biten isimler hep die’dir ve çoğulda -en alır: die Wohnung → die Wohnungen.','Nomen auf -ung sind immer feminin, Plural mit -en: die Wohnung → die Wohnungen.','Nouns ending in -ung are always die and add -en in the plural: die Wohnung → die Wohnungen.','الأسماء المنتهية بـ ‎-ung مؤنثة دائمًا (die) وتأخذ ‎-en في الجمع: die Wohnung → die Wohnungen.','Іменники на -ung завжди die, у множині -en: die Wohnung → die Wohnungen.','Les noms en -ung sont toujours die et prennent -en au pluriel : die Wohnung → die Wohnungen.'),
 capitalNouns:r('Almancada bütün isimler büyük harfle başlar (Wohnzimmer, Anzeige, Montag); sıfatlar, fiiller ve ich küçük yazılır (groß, hell, gelesen). Cümlenin ilk kelimesi de büyük başlar.','Nomen schreibt man groß (Wohnzimmer, Anzeige, Montag), Adjektive, Verben und ich klein (groß, hell, gelesen). Der Satzanfang ist groß.','In German every noun starts with a capital letter (Wohnzimmer, Anzeige, Montag); adjectives, verbs and ich stay small (groß, hell, gelesen). The first word of a sentence is capitalised too.','في الألمانية تبدأ كل الأسماء بحرف كبير (Wohnzimmer، Anzeige، Montag)، أما الصفات والأفعال و ich فبحرف صغير (groß، hell، gelesen). وأول كلمة في الجملة تبدأ بحرف كبير أيضًا.','У німецькій усі іменники пишуться з великої літери (Wohnzimmer, Anzeige, Montag), прикметники, дієслова та ich — з малої (groß, hell, gelesen). Перше слово речення — теж з великої.','En allemand, tous les noms prennent une majuscule (Wohnzimmer, Anzeige, Montag) ; adjectifs, verbes et ich restent en minuscules (groß, hell, gelesen). Le premier mot de la phrase prend aussi une majuscule.'),
 familySingular:r('die Familie çok kişiden oluşsa da dilbilgisinde tekildir: Die Familie hat … (haben değil).','die Familie ist Singular: Die Familie hat … (nicht haben).','die Familie has many people, but it is grammatically singular: Die Familie hat … (not haben).','كلمة die Familie تضم عدة أشخاص، لكنها مفردة نحويًا: Die Familie hat … (وليس haben).','die Familie складається з кількох людей, але граматично це однина: Die Familie hat … (не haben).','die Familie compte plusieurs personnes, mais elle est au singulier : Die Familie hat … (et non haben).'),
 pluralSubject:r('Özne çoğulsa fiil haben olur: meine Eltern = sie → haben. Mein Bruder und ich = wir → haben.','Plural-Subjekt → haben: meine Eltern = sie → haben. Mein Bruder und ich = wir → haben.','A plural subject takes haben: meine Eltern = sie → haben. Mein Bruder und ich = wir → haben.','إذا كان الفاعل جمعًا نستخدم haben: meine Eltern = sie → haben. و Mein Bruder und ich = wir → haben.','Підмет у множині → haben: meine Eltern = sie → haben. Mein Bruder und ich = wir → haben.','Un sujet pluriel prend haben : meine Eltern = sie → haben. Mein Bruder und ich = wir → haben.'),
 duIhr:r('İki kişiye samimi hitap: du und Mia = ihr → habt. Tek kişiye: du → hast.','du und Mia = ihr → habt. Nur du → hast.','Speaking informally to two people: du und Mia = ihr → habt. To one person: du → hast.','عند مخاطبة شخصين بشكل ودي: du und Mia = ihr → habt. ولشخص واحد: du → hast.','Неформально до двох людей: du und Mia = ihr → habt. До однієї: du → hast.','Pour tutoyer deux personnes : du und Mia = ihr → habt. Une seule personne : du → hast.'),
 partIrregular:r('finden, lesen, schreiben, schlafen, essen, trinken, sehen düzensizdir: ge- … -en (gefunden, gelesen, geschlafen). “gefindet” gibi biçimler yoktur.','Unregelmäßig: ge- … -en (gefunden, gelesen, geschlafen). „gefindet“ gibt es nicht.','finden, lesen, schreiben, schlafen, essen, trinken and sehen are irregular: ge- … -en (gefunden, gelesen, geschlafen). Forms like “gefindet” do not exist.','الأفعال finden و lesen و schreiben و schlafen و essen و trinken و sehen غير منتظمة: ge- … -en (gefunden، gelesen، geschlafen). صيغ مثل „gefindet“ غير موجودة.','finden, lesen, schreiben, schlafen, essen, trinken, sehen — неправильні: ge- … -en (gefunden, gelesen, geschlafen). Форм на кшталт „gefindet“ немає.','finden, lesen, schreiben, schlafen, essen, trinken et sehen sont irréguliers : ge- … -en (gefunden, gelesen, geschlafen). Des formes comme « gefindet » n’existent pas.'),
 partEt:r('Düzenli fiillerde kök -t veya -d ile bitiyorsa -et eklenir: arbeiten → gearbeitet, reden → geredet, mieten → gemietet.','Regelmäßige Verben mit Stamm auf -t oder -d → -et: gearbeitet, geredet, gemietet.','Regular verbs whose stem ends in -t or -d take -et: arbeiten → gearbeitet, reden → geredet, mieten → gemietet.','الأفعال المنتظمة التي ينتهي جذرها بـ ‎-t أو ‎-d تأخذ ‎-et: arbeiten → gearbeitet، reden → geredet، mieten → gemietet.','Правильні дієслова з основою на -t або -d отримують -et: arbeiten → gearbeitet, reden → geredet, mieten → gemietet.','Les verbes réguliers dont le radical finit par -t ou -d prennent -et : arbeiten → gearbeitet, reden → geredet, mieten → gemietet.'),
 partFrueh:r('frühstücken ayrılan bir fiil değildir: ge- en başa gelir → gefrühstückt (frühgestückt değil).','frühstücken ist nicht trennbar: gefrühstückt (nicht frühgestückt).','frühstücken is not a separable verb: ge- goes at the very front → gefrühstückt (not frühgestückt).','الفعل frühstücken ليس فعلًا منفصلًا: تأتي ge- في البداية → gefrühstückt (وليس frühgestückt).','frühstücken — не відокремлюване дієслово: ge- стоїть на самому початку → gefrühstückt (не frühgestückt).','frühstücken n’est pas un verbe séparable : ge- se place tout au début → gefrühstückt (et non frühgestückt).'),
 hangen:r('Bir şeyi asmak (hängen + nesne) düzenlidir: Ich habe die Lampe aufgehängt / gehängt. gehangen ise “asılı durdu” demektir.','hängen mit Objekt ist regelmäßig: Ich habe die Lampe gehängt. gehangen = etwas hing irgendwo.','To hang something (hängen + object) is regular: Ich habe die Lampe gehängt. gehangen means “was hanging”.','تعليق شيء (hängen مع مفعول به) فعل منتظم: Ich habe die Lampe gehängt. أما gehangen فتعني «كان معلّقًا».','Вішати щось (hängen + додаток) — правильне дієслово: Ich habe die Lampe gehängt. gehangen означає «висіло».','Accrocher quelque chose (hängen + complément) est régulier : Ich habe die Lampe gehängt. gehangen veut dire « était accroché ».'),
 verbSecond:r('Cümle zamanla başlasa bile (Gestern, Am Samstag) çekimli fiil 2. sırada kalır, özne fiilden sonra gelir: Gestern haben wir … “Gestern wir haben” denmez.','Auch nach Gestern / Am Samstag steht das Verb auf Position 2, das Subjekt danach: Gestern haben wir …','Even when the sentence starts with a time phrase (Gestern, Am Samstag), the conjugated verb stays in position 2 and the subject follows: Gestern haben wir … Never “Gestern wir haben”.','حتى إذا بدأت الجملة بعبارة زمنية (Gestern، Am Samstag) يبقى الفعل المصرَّف في الموضع الثاني ويأتي الفاعل بعده: Gestern haben wir … ولا نقول „Gestern wir haben“.','Навіть якщо речення починається з часу (Gestern, Am Samstag), відмінюване дієслово стоїть на 2-му місці, а підмет — після нього: Gestern haben wir … Не можна „Gestern wir haben“.','Même si la phrase commence par un repère de temps (Gestern, Am Samstag), le verbe conjugué reste en 2e position et le sujet vient après : Gestern haben wir … Jamais « Gestern wir haben ».'),
 bracket:r('Perfekt’te haben 2. sırada, Partizip II cümlenin en sonundadır; geri kalan her şey arada durur: Am Samstag hat Ali eine Lampe gekauft.','haben auf Position 2, Partizip II ganz am Ende: Am Samstag hat Ali eine Lampe gekauft.','In the Perfekt, haben is in position 2 and the participle goes to the very end, with everything else in between: Am Samstag hat Ali eine Lampe gekauft.','في Perfekt يأتي haben في الموضع الثاني واسم المفعول في آخر الجملة، وكل شيء آخر بينهما: Am Samstag hat Ali eine Lampe gekauft.','У Perfekt haben стоїть на 2-му місці, а дієприкметник — у самому кінці; усе інше між ними: Am Samstag hat Ali eine Lampe gekauft.','Au Perfekt, haben est en 2e position et le participe tout à la fin ; le reste se place entre les deux : Am Samstag hat Ali eine Lampe gekauft.'),
 questionWord:r('W-sorusunda soru kelimesi 1., çekimli fiil 2. sıradadır; Partizip yine en sondadır: Wo habt ihr die Wohnung gefunden?','W-Frage: W-Wort – Verb – Subjekt … Partizip am Ende: Wo habt ihr die Wohnung gefunden?','In a W-question the question word comes first, the conjugated verb second and the participle still last: Wo habt ihr die Wohnung gefunden?','في سؤال W تأتي أداة الاستفهام أولًا ثم الفعل المصرَّف، ويبقى اسم المفعول في النهاية: Wo habt ihr die Wohnung gefunden?','У W-питанні питальне слово перше, відмінюване дієслово друге, а дієприкметник — у кінці: Wo habt ihr die Wohnung gefunden?','Dans une question en W, le mot interrogatif est en 1re position, le verbe conjugué en 2e et le participe toujours à la fin : Wo habt ihr die Wohnung gefunden ?'),
 anrede:r('Lieber erkeğe, Liebe kadına yazılır: Lieber Tom, Liebe Mila. Resmîde: Sehr geehrter Herr …, Sehr geehrte Frau … Hitaptan sonra virgül konur.','Lieber Tom, Liebe Mila; formell: Sehr geehrter Herr …, Sehr geehrte Frau … Danach ein Komma.','Lieber for a man, Liebe for a woman: Lieber Tom, Liebe Mila. Formal: Sehr geehrter Herr …, Sehr geehrte Frau … Put a comma after the greeting.','Lieber للرجل و Liebe للمرأة: Lieber Tom، Liebe Mila. وفي الرسمي: Sehr geehrter Herr …، Sehr geehrte Frau … وبعد التحية نضع فاصلة.','Lieber — до чоловіка, Liebe — до жінки: Lieber Tom, Liebe Mila. Офіційно: Sehr geehrter Herr …, Sehr geehrte Frau … Після звертання ставимо кому.','Lieber pour un homme, Liebe pour une femme : Lieber Tom, Liebe Mila. Formel : Sehr geehrter Herr …, Sehr geehrte Frau … Une virgule suit la formule d’appel.'),
 gruss:r('Samimi kapanış: Viele Grüße / Liebe Grüße. Resmî kapanış: Mit freundlichen Grüßen — mit’ten sonra Grüßen (-n ile) yazılır.','Informell: Viele Grüße / Liebe Grüße. Formell: Mit freundlichen Grüßen (nach mit: Grüßen).','Informal: Viele Grüße / Liebe Grüße. Formal: Mit freundlichen Grüßen — after mit it is Grüßen with -n.','غير رسمي: Viele Grüße / Liebe Grüße. رسمي: Mit freundlichen Grüßen — بعد mit نكتب Grüßen مع ‎-n.','Неформально: Viele Grüße / Liebe Grüße. Офіційно: Mit freundlichen Grüßen — після mit пишемо Grüßen із -n.','Informel : Viele Grüße / Liebe Grüße. Formel : Mit freundlichen Grüßen — après mit, on écrit Grüßen avec -n.'),
 letterComma:r('Hitaptaki virgülden sonra mektup küçük harfle devam eder: Liebe Mila, wir haben … İsimler (Wohnung) yine büyük yazılır.','Nach dem Komma in der Anrede geht es klein weiter: Liebe Mila, wir haben … Nomen bleiben groß.','After the comma of the greeting, the letter continues in lower case: Liebe Mila, wir haben … Nouns (Wohnung) keep their capital.','بعد الفاصلة في التحية تستمر الرسالة بحرف صغير: Liebe Mila, wir haben … وتبقى الأسماء (Wohnung) بحرف كبير.','Після коми у звертанні лист продовжується з малої літери: Liebe Mila, wir haben … Іменники (Wohnung) усе одно з великої.','Après la virgule de la formule d’appel, la lettre continue en minuscule : Liebe Mila, wir haben … Les noms (Wohnung) gardent leur majuscule.'),
 questionCapital:r('Soru cümlesi ? ile biter ve büyük harfle başlar. Günler (Sonntag) isim olduğu için büyük yazılır.','Fragen beginnen groß und enden mit ?. Wochentage (Sonntag) schreibt man groß.','A question starts with a capital letter and ends with ?. Days (Sonntag) are nouns, so they take a capital too.','السؤال يبدأ بحرف كبير وينتهي بـ ?. وأيام الأسبوع (Sonntag) أسماء فتُكتب بحرف كبير أيضًا.','Питання починається з великої літери й закінчується знаком ?. Дні тижня (Sonntag) — іменники, тож теж з великої.','Une question commence par une majuscule et se termine par ?. Les jours (Sonntag) sont des noms : ils prennent aussi une majuscule.'),
 separable:r('abgeben, abstellen, ablesen ayrılan fiillerdir: şimdiki zamanda ön ek sona gider (Er liest die Heizung ab.), Perfekt’te ge- ortaya girer (abgegeben, abgestellt).','Trennbare Verben: Präsens – Er liest die Heizung ab. Perfekt – ab-ge-geben, ab-ge-stellt.','abgeben, abstellen and ablesen are separable: in the present the prefix goes to the end (Er liest die Heizung ab.), in the Perfekt ge- goes in the middle (abgegeben, abgestellt).','الأفعال abgeben و abstellen و ablesen أفعال منفصلة: في المضارع تذهب البادئة إلى آخر الجملة (Er liest die Heizung ab.)، وفي Perfekt تدخل ge- في الوسط (abgegeben، abgestellt).','abgeben, abstellen, ablesen — відокремлювані: у теперішньому часі префікс іде в кінець (Er liest die Heizung ab.), у Perfekt ge- стоїть посередині (abgegeben, abgestellt).','abgeben, abstellen et ablesen sont séparables : au présent, le préfixe va à la fin (Er liest die Heizung ab.), au Perfekt, ge- se place au milieu (abgegeben, abgestellt).'),
 noGe:r('be- ile başlayan (bekommen, bezahlen, besichtigen) ve -ieren ile biten (telefonieren) fiiller Perfekt’te ge- almaz: bekommen, bezahlt, telefoniert.','Kein ge- bei be-Verben und Verben auf -ieren: bekommen, bezahlt, besichtigt, telefoniert.','Verbs starting with be- (bekommen, bezahlen, besichtigen) and verbs ending in -ieren (telefonieren) take no ge-: bekommen, bezahlt, telefoniert.','الأفعال التي تبدأ بـ be- (bekommen، bezahlen، besichtigen) والمنتهية بـ ‎-ieren (telefonieren) لا تأخذ ge- في Perfekt: bekommen، bezahlt، telefoniert.','Дієслова з be- (bekommen, bezahlen, besichtigen) і на -ieren (telefonieren) не мають ge-: bekommen, bezahlt, telefoniert.','Les verbes en be- (bekommen, bezahlen, besichtigen) et en -ieren (telefonieren) ne prennent pas ge- : bekommen, bezahlt, telefoniert.'),
 noticeInfinitive:r('Duyurularda kısa talimat için mastar sona konur: Bitte die Haustür schließen! Kinderwagen bitte nicht im Treppenhaus abstellen.','Aushänge: Infinitiv am Ende – Bitte die Haustür schließen!','Notices give short instructions with the infinitive at the end: Bitte die Haustür schließen!','في الإعلانات تُكتب التعليمات القصيرة بالمصدر في آخر الجملة: Bitte die Haustür schließen!','В оголошеннях короткі інструкції пишуть з інфінітивом у кінці: Bitte die Haustür schließen!','Dans les avis, les consignes courtes mettent l’infinitif à la fin : Bitte die Haustür schließen !'),
 modalBracket:r('können ile çekimli fiil soruda 1., düz cümlede 2. sıradadır; asıl fiil mastar hâlinde en sona gider: Können Sie bitte mein Paket annehmen?','können + … + Infinitiv am Ende: Können Sie bitte mein Paket annehmen?','With können the conjugated verb comes first in a yes/no question (second in a statement) and the main verb goes to the end as an infinitive: Können Sie bitte mein Paket annehmen?','مع können يأتي الفعل المصرَّف أولًا في سؤال نعم/لا (وثانيًا في الجملة الخبرية)، والفعل الأساسي في آخر الجملة بصيغة المصدر: Können Sie bitte mein Paket annehmen?','З können відмінюване дієслово стоїть першим у питанні так/ні (другим у розповідному реченні), а основне дієслово — в кінці в інфінітиві: Können Sie bitte mein Paket annehmen?','Avec können, le verbe conjugué est en 1re position dans une question oui/non (en 2e dans une affirmation) et le verbe principal va à la fin, à l’infinitif : Können Sie bitte mein Paket annehmen ?'),
 duKannst:r('Fiil hitap edilen kişiye uymalı. du ile: du kannst, du hast. Sie ile: Können Sie …?, Haben Sie …?','du kannst / du hast – Sie können / Sie haben.','The verb must match the person you address. With du: du kannst, du hast. With Sie: Können Sie …?, Haben Sie …?','يجب أن يتوافق الفعل مع الشخص المخاطَب. مع du: du kannst، du hast. ومع Sie: Können Sie …؟، Haben Sie …؟','Дієслово має узгоджуватися з тим, до кого звертаєшся. З du: du kannst, du hast. З Sie: Können Sie …?, Haben Sie …?','Le verbe doit correspondre à la personne à qui l’on parle. Avec du : du kannst, du hast. Avec Sie : Können Sie … ?, Haben Sie … ?'),
 helfenDativ:r('helfen fiilinden sonra mir / dir / Ihnen gelir (mich / dich değil): Kannst du mir helfen?','helfen + Dativ: mir, dir, Ihnen – nicht mich, dich.','helfen takes mir / dir / Ihnen (not mich / dich): Kannst du mir helfen?','بعد الفعل helfen نستخدم mir / dir / Ihnen (وليس mich / dich): Kannst du mir helfen?','helfen вимагає mir / dir / Ihnen (не mich / dich): Kannst du mir helfen?','helfen se construit avec mir / dir / Ihnen (et non mich / dich) : Kannst du mir helfen ?'),
 readNotice:r('Duyuruda birden fazla gün, saat ve kişi var. Soruyu metindeki tam cümleyle eşleştir: Dienstag – Techniker, Montag – Schlüssel.','Im Aushang stehen mehrere Tage, Zeiten und Personen. Finde genau den passenden Satz.','The notice mentions several days, times and people. Match the question to the exact sentence: Dienstag – Techniker, Montag – Schlüssel.','يذكر الإعلان عدة أيام وأوقات وأشخاص. طابق السؤال مع الجملة الصحيحة تمامًا: Dienstag – Techniker، Montag – Schlüssel.','В оголошенні кілька днів, годин і людей. Знайди саме те речення, про яке питання: Dienstag – Techniker, Montag – Schlüssel.','L’avis cite plusieurs jours, heures et personnes. Retrouve la phrase exacte : Dienstag – Techniker, Montag – Schlüssel.'),
 readingOrder:r('Metinde benzer bilgiler var (gazete, internet, süpermarket). Sıra kelimelerine dikkat et: zuerst (önce), dann (sonra), vor einer Woche (bir hafta önce).','Achte auf zuerst, dann, vor einer Woche.','The text has similar details (newspaper, internet, supermarket). Watch the order words: zuerst, dann, vor einer Woche.','في النص تفاصيل متشابهة (الجريدة، الإنترنت، السوبرماركت). انتبه لكلمات الترتيب: zuerst، dann، vor einer Woche.','У тексті схожі деталі (газета, інтернет, супермаркет). Зважай на слова порядку: zuerst, dann, vor einer Woche.','Le texte contient des détails semblables (journal, Internet, supermarché). Fais attention aux mots d’ordre : zuerst, dann, vor einer Woche.'),
 readingNumbers:r('Metinde birden fazla sayı var. Sayının hangi kelimeyle geçtiğine bak: zwanzig E-Mails, drei Zimmer.','Welche Zahl gehört zu welchem Wort? zwanzig E-Mails, drei Zimmer.','The text has several numbers. Check which word each number belongs to: zwanzig E-Mails, drei Zimmer.','في النص أكثر من رقم. انظر إلى الكلمة التي يرتبط بها كل رقم: zwanzig E-Mails، drei Zimmer.','У тексті кілька чисел. Дивись, до якого слова належить кожне: zwanzig E-Mails, drei Zimmer.','Le texte contient plusieurs nombres. Regarde à quel mot chacun se rapporte : zwanzig E-Mails, drei Zimmer.'),
 femaleIn:r('-in eki kadını gösterir: der Kollege (erkek) → die Kollegin (kadın). Metinde seine Kollegin yazıyor.','-in = weiblich: der Kollege → die Kollegin. Im Text steht seine Kollegin.','The ending -in marks a woman: der Kollege (man) → die Kollegin (woman). The text says seine Kollegin.','اللاحقة ‎-in تدل على المؤنث: der Kollege (رجل) → die Kollegin (امرأة). وفي النص: seine Kollegin.','Суфікс -in позначає жінку: der Kollege (чоловік) → die Kollegin (жінка). У тексті: seine Kollegin.','La terminaison -in indique une femme : der Kollege (homme) → die Kollegin (femme). Le texte dit seine Kollegin.'),
 readingDetail:r('Tahmine göre değil, metne göre cevap ver: Deniz daireyi yalnızca gezip gördü (besichtigt); henüz kiralamadı, cevap bekliyor.','Nur besichtigt – noch nicht gemietet. Deniz wartet auf eine Antwort.','Answer from the text, not from a guess: Deniz only viewed the flat (besichtigt); he has not rented it yet and is waiting for an answer.','أجب من النص لا من التخمين: دنيز عاين الشقة فقط (besichtigt)، ولم يستأجرها بعد وهو ينتظر الرد.','Відповідай за текстом, а не навздогад: Деніз лише оглянув квартиру (besichtigt), ще не орендував і чекає на відповідь.','Réponds d’après le texte, pas au hasard : Deniz a seulement visité l’appartement (besichtigt) ; il ne l’a pas encore loué et attend une réponse.'),
 seitVor:r('seit = -dır / -den beri (hâlâ sürüyor, şimdiki zaman): Ich wohne seit einem Jahr hier. vor = önce (bitti, Perfekt): Ich habe vor einem Jahr eine Wohnung gefunden.','seit: dauert noch an (Präsens). vor: ist vorbei (Perfekt).','seit = for / since (still true, present tense): Ich wohne seit einem Jahr hier. vor = ago (finished, Perfekt): Ich habe vor einem Jahr eine Wohnung gefunden.','seit = منذ (ما زال مستمرًا، بالمضارع): Ich wohne seit einem Jahr hier. و vor = قبل (انتهى، بـ Perfekt): Ich habe vor einem Jahr eine Wohnung gefunden.','seit = вже / від (триває досі, теперішній час): Ich wohne seit einem Jahr hier. vor = тому (завершено, Perfekt): Ich habe vor einem Jahr eine Wohnung gefunden.','seit = depuis (toujours vrai, présent) : Ich wohne seit einem Jahr hier. vor = il y a (terminé, Perfekt) : Ich habe vor einem Jahr eine Wohnung gefunden.'),
 reverseCard:r('Fiil kartlarını iki yönde de çalış: Partizip II’den mastarı bulabilmelisin. gefunden ← finden, geschrieben ← schreiben.','Lerne beide Richtungen: gefunden ← finden, geschrieben ← schreiben.','Practise verb cards in both directions: from the participle back to the infinitive. gefunden ← finden, geschrieben ← schreiben.','تدرّب على بطاقات الأفعال في الاتجاهين: من اسم المفعول إلى المصدر. gefunden ← finden، geschrieben ← schreiben.','Тренуй картки дієслів в обидва боки: від дієприкметника до інфінітива. gefunden ← finden, geschrieben ← schreiben.','Entraîne-toi dans les deux sens : du participe vers l’infinitif. gefunden ← finden, geschrieben ← schreiben.'),
 imperativeDu:r('du için emir kipinde du ve sondaki -st / -t düşer: du fragst → Frag!, du liest → Lies! e → ie değişimi kalır (lesen → lies).','Imperativ mit du: du fragst → Frag!, du liest → Lies!','For the du-imperative drop du and the ending -st (or -t): du fragst → Frag!, du liest → Lies! The e → ie change stays (lesen → lies).','في صيغة الأمر لـ du نحذف du والنهاية ‎-st (أو ‎-t): du fragst → Frag!، du liest → Lies! ويبقى تغيّر e → ie (lesen → lies).','Наказовий спосіб для du: відкидаємо du і закінчення -st (або -t): du fragst → Frag!, du liest → Lies! Зміна e → ie зберігається (lesen → lies).','À l’impératif avec du, on enlève du et la terminaison -st (ou -t) : du fragst → Frag !, du liest → Lies ! Le changement e → ie reste (lesen → lies).'),
} satisfies Record<string,Translations>;
export type TrapReason=keyof typeof trapReasons;

export const trapPassages={
 notice:{de:'Liebe Mieterinnen und Mieter, am Dienstag kommt der Techniker und liest die Heizung ab. Er ist von 8 bis 12 Uhr im Haus. Sie sind am Dienstag nicht zu Hause? Dann geben Sie Ihren Schlüssel bis Montag beim Hausmeister ab. Mit freundlichen Grüßen, Ihre Hausverwaltung',
  meaning:m('Sevgili kiracılar, salı günü teknisyen gelip kalorifer sayaçlarını okuyacak. Saat 8’den 12’ye kadar binada olacak. Salı günü evde değil misiniz? O zaman anahtarınızı pazartesiye kadar bina görevlisine bırakın. Saygılarımızla, bina yönetiminiz','Dear tenants, on Tuesday the technician is coming to read the heating meters. He will be in the building from 8 to 12. Won’t you be at home on Tuesday? Then please leave your key with the caretaker by Monday. Kind regards, your property management','أعزاءنا السكان، يأتي الفني يوم الثلاثاء ليقرأ عدادات التدفئة. سيكون في المبنى من الساعة 8 حتى 12. لن تكونوا في البيت يوم الثلاثاء؟ إذن سلّموا مفتاحكم لمسؤول المبنى حتى يوم الاثنين. مع خالص التحيات، إدارة المبنى','Шановні мешканці, у вівторок прийде технік і зніме показники опалення. Він буде в будинку з 8 до 12 години. Вас не буде вдома у вівторок? Тоді залиште, будь ласка, ключ доглядачеві будинку до понеділка. З повагою, ваша керуюча компанія','Chers locataires, mardi, le technicien vient relever les compteurs de chauffage. Il sera dans l’immeuble de 8 h à 12 h. Vous n’êtes pas chez vous mardi ? Alors déposez votre clé chez le concierge d’ici lundi. Cordialement, votre gestion d’immeuble')},
 deniz:{de:'Deniz sucht seit einem Jahr eine Wohnung in Köln. Zuerst hat er in der Zeitung gesucht, aber die Wohnungen waren zu teuer. Dann hat er im Internet gesucht und zwanzig E-Mails geschrieben. Niemand hat geantwortet. Vor einer Woche hat seine Kollegin einen Zettel im Supermarkt gesehen: drei Zimmer, Balkon, nicht teuer. Deniz hat sofort telefoniert. Am Samstag hat er die Wohnung besichtigt. Jetzt wartet er auf eine Antwort.',
  meaning:m('Deniz bir yıldır Köln’de daire arıyor. Önce gazetede aradı ama daireler çok pahalıydı. Sonra internette aradı ve yirmi e-posta yazdı. Kimse cevap vermedi. Bir hafta önce (kadın) iş arkadaşı süpermarkette bir ilan kâğıdı gördü: üç oda, balkon, pahalı değil. Deniz hemen telefon etti. Cumartesi daireyi gezip gördü. Şimdi bir cevap bekliyor.','Deniz has been looking for a flat in Cologne for a year. First he searched in the newspaper, but the flats were too expensive. Then he searched online and wrote twenty emails. Nobody answered. A week ago his (female) colleague saw a note in the supermarket: three rooms, balcony, not expensive. Deniz phoned straight away. On Saturday he viewed the flat. Now he is waiting for an answer.','يبحث دنيز منذ سنة عن شقة في كولونيا. في البداية بحث في الجريدة، لكن الشقق كانت غالية جدًا. ثم بحث على الإنترنت وكتب عشرين رسالة إلكترونية. لم يرد أحد. قبل أسبوع رأت زميلته ورقة إعلان في السوبرماركت: ثلاث غرف، شرفة، ليست غالية. اتصل دنيز فورًا. يوم السبت عاين الشقة. والآن ينتظر الرد.','Деніз уже рік шукає квартиру в Кельні. Спочатку він шукав у газеті, але квартири були надто дорогі. Потім він шукав в інтернеті й написав двадцять електронних листів. Ніхто не відповів. Тиждень тому його колега побачила оголошення в супермаркеті: три кімнати, балкон, недорого. Деніз одразу зателефонував. У суботу він оглянув квартиру. Тепер він чекає на відповідь.','Deniz cherche un appartement à Cologne depuis un an. D’abord, il a cherché dans le journal, mais les appartements étaient trop chers. Ensuite, il a cherché sur Internet et a écrit vingt e-mails. Personne n’a répondu. Il y a une semaine, sa collègue a vu une annonce au supermarché : trois pièces, un balcon, pas cher. Deniz a tout de suite téléphoné. Samedi, il a visité l’appartement. Maintenant, il attend une réponse.')},
} as const;
export type TrapPassage=keyof typeof trapPassages;

export type HousingTrap={section:'a'|'b'|'c'|'d';step:number;id:string;why:TrapReason;rule:Rule;answer:string;traps:readonly [string,string,string];meaning:Translations;
 /** Sentence with ___ for the answer; a trailing (hint) is dropped from the solved sentence. */
 gap?:string;
 /** false: only the four-option version (the writing form already exists elsewhere or cannot be typed fairly). */
 write?:boolean;strictCase?:boolean;accepted?:string[];
 /** Writing version shows the words in lower case: the learner must restore capitals. */
 lower?:boolean;art?:string;passage?:TrapPassage};

type Row=Omit<HousingTrap,'section'|'step'>;
const at=(section:HousingTrap['section'],step:number,rows:Row[])=>rows.map(row=>({section,step,...row}));

